use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Returns true if the current terminal, detected through various environment"] # [doc = " variables, is known to support hyperlink rendering."] pub fn supports_hyperlinks () -> bool { if let Ok (arg) = std :: env :: var ("FORCE_HYPERLINK") { return arg . trim () != "0" ; } if std :: env :: var ("DOMTERM") . is_ok () { return true ; } if let Ok (version) = std :: env :: var ("VTE_VERSION") { if version . parse () . unwrap_or (0) >= 5000 { return true ; } } if let Ok (program) = std :: env :: var ("TERM_PROGRAM") { if matches ! (& program [..] , "Hyper" | "iTerm.app" | "terminology" | "WezTerm" | "vscode" | "ghostty") { return true ; } } if let Ok (term) = std :: env :: var ("TERM") { if matches ! (& term [..] , "xterm-kitty" | "alacritty" | "alacritty-direct") { return true ; } } if let Ok (term) = std :: env :: var ("COLORTERM") { if matches ! (& term [..] , "xfce4-terminal") { return true ; } } std :: env :: var ("WT_SESSION") . is_ok () || std :: env :: var ("KONSOLE_VERSION") . is_ok () }